// 来源：beUI <https://beui.dev/r/funnel-chart.json>，上游文件 components/charts/funnel-chart.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点、import 路径（明细见 vendor.lock.json）
"use client";
// beui.dev/charts/funnel-chart

import { createContext, useContext, useMemo, type ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { NumberTicker } from "@/components/vendor/beui/motion/number-ticker";
import { Tooltip } from "@/components/vendor/beui/motion/tooltip";
import { EASE_OUT } from "@/components/vendor/beui/lib/ease";
import { cn } from "@/lib/utils";
import { buildFunnel, funnelPath, type FunnelStage } from "./funnel-chart/model";

const defaultFormat = (value: number) =>
  value.toLocaleString("en-US", { maximumFractionDigits: 2 });
const percentage = (value: number | null) => (value === null ? "—" : `${value.toFixed(1)}%`);
const colors = ["#8b5cf6", "#7774ef", "#548ee4", "#2ca6bc", "#14b8a6"];
export interface FunnelChartProps {
  /** Ordered stages with finite, nonnegative counts; duplicate IDs are omitted. */
  stages: readonly FunnelStage[];
  direction?: "vertical" | "horizontal";
  unit?: string;
  label?: string;
  formatValue?: (value: number) => string;
  className?: string;
  children?: ReactNode;
}
const Context = createContext<
  | (ReturnType<typeof buildFunnel> & {
      direction: "vertical" | "horizontal";
      unit: string;
      formatValue: (value: number) => string;
    })
  | null
>(null);
export function useFunnelChart() {
  const context = useContext(Context);
  if (!context) throw new Error("Funnel chart parts must be inside FunnelChart");
  return context;
}
export function FunnelChart({
  stages,
  direction = "vertical",
  unit = "people",
  label = "Conversion funnel",
  formatValue = defaultFormat,
  className,
  children,
}: FunnelChartProps) {
  const model = useMemo(() => buildFunnel(stages), [stages]);
  return (
    <Context.Provider value={{ ...model, direction, unit, formatValue }}>
      <section aria-label={label} className={cn("w-full space-y-6", className)}>
        {children === undefined ? (
          <>
            <FunnelChartPlot />
            <FunnelChartSummary />
          </>
        ) : (
          children
        )}
      </section>
    </Context.Provider>
  );
}
export function FunnelChartPlot({ className }: { className?: string }) {
  const { rows, direction, unit, formatValue } = useFunnelChart();
  const reduced = useReducedMotion();
  if (!rows.length)
    return (
      <p className={cn("py-16 text-center text-sm text-muted-foreground", className)}>
        No funnel data
      </p>
    );
  const horizontal = direction === "horizontal";
  const proportions = rows.map((stage) => stage.proportion);
  return (
    <div className={cn("space-y-5", className)}>
      <div className="overflow-x-auto">
        <div
          className="relative"
          style={{
            height: horizontal ? 300 : Math.max(320, rows.length * 72),
            minWidth: horizontal ? rows.length * 110 : 240,
          }}
        >
          <svg
            aria-hidden="true"
            viewBox="0 0 1000 500"
            preserveAspectRatio="none"
            className="absolute inset-0 h-full w-full"
          >
            {rows.map((stage, index) => (
              <motion.path
                key={stage.id}
                fill={stage.color ?? colors[index % colors.length]}
                initial={false}
                // A shared path interpolation keeps adjacent curved boundaries connected.
                animate={{ d: funnelPath(proportions, index, direction) }}
                transition={{ duration: reduced ? 0 : 0.28, ease: EASE_OUT }}
              />
            ))}
          </svg>
          <ol
            aria-label="Funnel stages"
            className="absolute inset-0 grid"
            style={
              horizontal
                ? { gridTemplateColumns: `repeat(${rows.length}, 1fr)` }
                : { gridTemplateRows: `repeat(${rows.length}, 1fr)` }
            }
          >
            {rows.map((stage, index) => (
              <li key={stage.id} className="min-h-0 min-w-0">
                <Tooltip
                  wrapperClassName="block h-full w-full"
                  content={
                    <span className="flex flex-col gap-1.5 text-xs">
                      <span className="text-muted-foreground">{stage.label}</span>
                      <NumberTicker
                        value={stage.value}
                        format={() => formatValue(stage.value)}
                        suffix={` ${unit}`}
                        duration={0.35}
                        startOnView={false}
                        className="font-mono"
                      />
                      {index > 0 && (
                        <>
                          <span>{percentage(stage.stepConversion)} from previous stage</span>
                          <span className="text-muted-foreground">
                            {formatValue(Math.abs(stage.change ?? 0))}{" "}
                            {(stage.change ?? 0) > 0 ? "gained" : "dropped"}
                          </span>
                        </>
                      )}
                      <span className="text-muted-foreground">
                        {percentage(stage.conversion)} of starting total
                      </span>
                    </span>
                  }
                >
                  <button
                    type="button"
                    className="flex h-full w-full items-center justify-center outline-none transition-colors hover:bg-foreground/5 focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring"
                    aria-label={`${stage.label}: ${formatValue(stage.value)} ${unit}, ${percentage(stage.conversion)} of starting total`}
                  >
                    <span className="rounded bg-background/85 px-2 py-1 font-mono text-xs font-medium tabular-nums">
                      {formatValue(stage.value)}
                    </span>
                  </button>
                </Tooltip>
              </li>
            ))}
          </ol>
        </div>
      </div>
      <div className="flex flex-wrap justify-center gap-x-6 gap-y-3">
        {rows.map((stage, index) => (
          <span key={stage.id} className="inline-flex items-center gap-2 text-xs">
            <span
              aria-hidden="true"
              className="size-2 shrink-0 rounded-full"
              style={{ backgroundColor: stage.color ?? colors[index % colors.length] }}
            />
            <span>{stage.label}</span>
            <span className="font-mono text-[10px] text-muted-foreground">
              {percentage(stage.conversion)}
            </span>
          </span>
        ))}
      </div>
    </div>
  );
}
export function FunnelChartSummary({ className }: { className?: string }) {
  const { rows, first, last, conversion, formatValue, unit } = useFunnelChart();
  if (!rows.length) return null;
  return (
    <div
      className={cn(
        "flex flex-wrap items-center justify-between gap-3 border-t border-border pt-4 text-xs",
        className,
      )}
    >
      <span className="text-muted-foreground">
        {formatValue(first)} → {formatValue(last)} {unit}
      </span>
      <span className="flex items-center gap-2">
        <span className="text-muted-foreground">Overall conversion</span>
        <span className="font-mono font-medium tabular-nums">{percentage(conversion)}</span>
      </span>
    </div>
  );
}
export type { FunnelStage };

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/funnel-chart.json>，上游文件 components/charts/funnel-chart/model.ts
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点（明细见 vendor.lock.json）
export interface FunnelStage {
  /** Keep IDs stable when updating counts. */
  id: string;
  label: string;
  value: number;
  color?: string;
}

/** Preserve stage order; omit invalid counts and repeated identities. */
export function buildFunnel(stages: readonly FunnelStage[]) {
  const seen = new Set<string>();
  const valid = stages.filter((stage) => {
    if (seen.has(stage.id) || !Number.isFinite(stage.value) || stage.value < 0) return false;
    seen.add(stage.id);
    return true;
  });
  const first = valid[0]?.value ?? 0;
  const last = valid.at(-1)?.value ?? 0;
  const maximum = valid.reduce((max, stage) => Math.max(max, stage.value), 0);
  const rows = valid.map((stage, index) => {
    const previous = valid[index - 1]?.value;
    return {
      ...stage,
      proportion: maximum > 0 ? stage.value / maximum : 0,
      conversion: first > 0 ? (stage.value / first) * 100 : null,
      stepConversion:
        previous !== undefined && previous > 0 ? (stage.value / previous) * 100 : null,
      change: previous === undefined ? null : stage.value - previous,
    };
  });
  return { rows, first, last, conversion: first > 0 ? (last / first) * 100 : null };
}

/** Each stage's center width encodes its value; shared boundaries join without gaps. */
export function funnelPath(
  proportions: readonly number[],
  index: number,
  direction: "vertical" | "horizontal",
) {
  const value = proportions[index];
  const top = index === 0 ? value : (proportions[index - 1] + value) / 2;
  const bottom = index === proportions.length - 1 ? value : (value + proportions[index + 1]) / 2;
  const start = index / proportions.length;
  const end = (index + 1) / proportions.length;
  const middle = (start + end) / 2;
  const quarter = (end - start) / 4;
  const point = (cross: number, along: number) =>
    direction === "vertical" ? `${cross * 1000},${along * 500}` : `${along * 1000},${cross * 500}`;
  const left = (width: number) => 0.5 - width * 0.46;
  const right = (width: number) => 0.5 + width * 0.46;
  return `M${point(left(top), start)} L${point(right(top), start)} C${point(right(top), start + quarter)} ${point(right(value), middle - quarter)} ${point(right(value), middle)} C${point(right(value), middle + quarter)} ${point(right(bottom), end - quarter)} ${point(right(bottom), end)} L${point(left(bottom), end)} C${point(left(bottom), end - quarter)} ${point(left(value), middle + quarter)} ${point(left(value), middle)} C${point(left(value), middle - quarter)} ${point(left(top), start + quarter)} ${point(left(top), start)} Z`;
}

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/number-ticker.json>，上游文件 components/motion/number-ticker.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点、import 路径（明细见 vendor.lock.json）
"use client";
// beui.dev/components/motion/number

import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useMemo, useRef, useState } from "react";
import { EASE_OUT } from "@/components/vendor/beui/lib/ease";
import { cn } from "@/lib/utils";

export interface NumberTickerProps {
  value: number;
  /** Digits to pad to (left). */
  pad?: number;
  /** Per-digit roll duration in seconds. */
  duration?: number;
  /** Stagger between digits. */
  stagger?: number;
  /** Render only after the element enters the viewport. */
  startOnView?: boolean;
  prefix?: string;
  suffix?: string;
  /** Add a small blur during digit rolls. */
  blur?: boolean;
  className?: string;
  digitClassName?: string;
  /** Insert locale group separators (commas). Server-component safe. */
  locale?: boolean;
  /** Custom formatter. Client-only — server components must use `locale` instead. */
  format?: (value: number) => string;
}

const DIGIT_HEIGHT_EM = 1.1;
const DIGITS = Array.from({ length: 10 }, (_, n) => n);

export function NumberTicker({
  value,
  pad,
  duration = 0.9,
  stagger = 0.04,
  startOnView = true,
  prefix,
  suffix,
  blur = false,
  className,
  digitClassName,
  locale,
  format,
}: NumberTickerProps) {
  const containerRef = useRef<HTMLSpanElement>(null);
  const inView = useInView(containerRef, { once: true, amount: 0.6 });
  const [armed, setArmed] = useState(!startOnView);

  useEffect(() => {
    if (startOnView && inView) setArmed(true);
  }, [startOnView, inView]);

  const text = useMemo(() => {
    const rounded = Math.round(value);
    const formatted = format
      ? format(rounded)
      : locale
        ? rounded.toLocaleString()
        : rounded.toString();
    return pad ? formatted.padStart(pad, "0") : formatted;
  }, [value, pad, format, locale]);
  const glyphs = useMemo(() => {
    const chars = text.split("");
    // Key by place value (position from the right): a changing digit keeps its
    // identity and rolls to the new value instead of remounting and replaying
    // from 0. Growing numbers add glyphs on the left without re-keying the
    // ones, tens, hundreds already on screen.
    return chars.map((char, i) => ({ char, id: `g-${chars.length - 1 - i}` }));
  }, [text]);
  const readableText = `${prefix ?? ""}${text}${suffix ?? ""}`;

  // Stagger is an entrance flourish. Once the reveal has played, value
  // changes roll every digit immediately — a per-digit delay on live updates
  // reads as lag.
  const [entered, setEntered] = useState(false);
  useEffect(() => {
    if (!armed || entered) return;
    const total = (duration + glyphs.length * stagger) * 1000;
    const t = window.setTimeout(() => setEntered(true), total);
    return () => window.clearTimeout(t);
  }, [armed, entered, duration, stagger, glyphs.length]);

  return (
    <span
      ref={containerRef}
      className={cn("inline-flex items-center tabular-nums", className)}
    >
      <span className="sr-only">{readableText}</span>
      <span aria-hidden="true" className="inline-flex items-center">
        {prefix ? <span>{prefix}</span> : null}
        {glyphs.map(({ char, id }, i) => {
          const isDigit = /\d/.test(char);
          if (!isDigit) {
            return (
              <span key={id} className="inline-block">
                {char}
              </span>
            );
          }
          const digit = Number(char);
          return (
            <Digit
              key={id}
              digit={armed ? digit : 0}
              delay={entered ? 0 : i * stagger}
              duration={duration}
              blur={blur}
              className={digitClassName}
            />
          );
        })}
        {suffix ? <span>{suffix}</span> : null}
      </span>
    </span>
  );
}

function Digit({
  digit,
  delay,
  duration,
  blur,
  className,
}: {
  digit: number;
  delay: number;
  duration: number;
  blur: boolean;
  className?: string;
}) {
  const reduce = useReducedMotion();
  const columnRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (reduce || !blur || !columnRef.current || !Number.isFinite(digit)) {
      return;
    }

    const node = columnRef.current;
    const controls = animate(
      node,
      { filter: ["blur(10px)", "blur(0px)"] },
      {
        duration: Math.min(duration * 0.75, 0.32),
        delay,
        ease: EASE_OUT,
      },
    );

    return () => {
      controls.stop();
      node.style.filter = "blur(0px)";
    };
  }, [blur, delay, digit, duration, reduce]);

  return (
    <span
      className={cn("relative inline-block overflow-hidden", className)}
      style={{ height: `${DIGIT_HEIGHT_EM}em`, width: "1ch" }}
    >
      <motion.span
        ref={columnRef}
        initial={{ y: 0 }}
        animate={{ y: `-${digit * DIGIT_HEIGHT_EM}em` }}
        transition={
          reduce
            ? { duration: 0 }
            : { duration, delay, ease: EASE_OUT }
        }
        className="absolute inset-x-0 top-0 flex flex-col items-center will-change-[transform,filter]"
      >
        {DIGITS.map((n) => (
          <span
            key={n}
            className="flex h-[1.1em] items-center justify-center leading-none"
          >
            {n}
          </span>
        ))}
      </motion.span>
    </span>
  );
}

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/tooltip.json>，上游文件 components/motion/tooltip.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点、import 路径（明细见 vendor.lock.json）
"use client";
// beui.dev/components/motion/tooltip

import { AnimatePresence } from "motion/react";
import { TooltipPositioner } from "./tooltip/positioner";
import { useTooltipPointer } from "./tooltip/use-position";
import {
  cloneElement,
  isValidElement,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  type RefObject,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import { TooltipSurface } from "@/components/vendor/beui/motion/tooltip-surface";
import { useDismiss } from "@/components/vendor/beui/lib/hooks/use-dismiss";
import { useHoverGesture } from "@/components/vendor/beui/lib/hooks/use-hover-gesture";
import { useTapGesture } from "@/components/vendor/beui/lib/hooks/use-tap-gesture";
import { cn } from "@/lib/utils";

type Side = "top" | "right" | "bottom" | "left";

export interface TooltipProps {
  content: ReactNode;
  children?: ReactElement;
  /** Existing trigger for controlled integrations such as chart cells. */
  anchorRef?: RefObject<HTMLElement | SVGElement | null>;
  /** Point within the anchor, as fractions of its rendered width and height. */
  anchorPoint?: { x: number; y: number };
  /** Follow real pointer coordinates; keyboard focus still uses the anchor. */
  followCursor?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  id?: string;
  side?: Side;
  /** Delay before showing (ms). Default 120. */
  delay?: number;
  className?: string;
  /** Classes for the outer wrapper span. Use to fix baseline / fill parent. */
  wrapperClassName?: string;
}

// Once any tooltip has just closed, neighbouring tooltips open without the
// initial delay — moving along a toolbar feels instant after the first one.
const WARM_WINDOW_MS = 300;
let lastHiddenAt = 0;

export function Tooltip({
  content,
  children,
  side = "top",
  delay = 120,
  className,
  wrapperClassName,
  anchorRef: externalAnchorRef,
  anchorPoint,
  followCursor = false,
  open: controlledOpen,
  onOpenChange,
  id: providedId,
}: TooltipProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen ?? internalOpen;
  const setOpen = useCallback(
    (next: boolean) => {
      if (controlledOpen === undefined) setInternalOpen(next);
      onOpenChange?.(next);
    },
    [controlledOpen, onOpenChange],
  );
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wrapperRef = useRef<HTMLSpanElement>(null);
  const anchorRef = externalAnchorRef ?? wrapperRef;
  const hover = useHoverGesture();
  const floatingRef = useRef<HTMLSpanElement | null>(null);
  const pointer = useTooltipPointer(anchorRef, followCursor);
  const focused = useRef(false);

  const show = useCallback(() => {
    if (timer.current) clearTimeout(timer.current);
    if (open) return;
    const warm = Date.now() - lastHiddenAt < WARM_WINDOW_MS;
    if (warm) {
      setOpen(true);
      return;
    }
    timer.current = setTimeout(() => {
      setOpen(true);
    }, delay);
  }, [delay, setOpen, open]);

  const hide = useCallback(() => {
    if (timer.current) {
      clearTimeout(timer.current);
      timer.current = null;
    }
    if (open) lastHiddenAt = Date.now();
    setOpen(false);
  }, [open, setOpen]);

  const leave = useCallback(() => {
    if (focused.current) return;
    if (timer.current) clearTimeout(timer.current);
    // Bridge the small physical gap to a stationary, readable tooltip.
    if (followCursor) hide();
    else timer.current = setTimeout(hide, 100);
  }, [followCursor, hide]);
  const insideTooltip = useCallback(
    (target: Element) => Boolean(floatingRef.current?.contains(target)),
    [],
  );

  // A finger never hovers, and Safari does not focus a button on tap either, so
  // the label is only reachable if the tap itself opens the tooltip. A click
  // carries no pointerType, so the pointerdown that preceded it is what says
  // whether this was a tap; keyboard activation arrives with no pointerdown at
  // all, and focus has already shown the label there.
  const tap = useTapGesture<boolean>();

  const toggleOnTap = useCallback(() => {
    const gesture = tap.take();
    if (!gesture || gesture.pointerType === "mouse") return;
    if (gesture.state) {
      hide();
      return;
    }
    if (timer.current) clearTimeout(timer.current);
    setOpen(true);
  }, [hide, tap, setOpen]);

  // ...and closed again by the next tap that lands somewhere else. The label
  // covers nothing interactive, so that tap passes through to what it hit.
  useDismiss(open, hide, anchorRef, { ignore: insideTooltip });

  useEffect(
    () => () => {
      if (timer.current) clearTimeout(timer.current);
    },
    [],
  );

  if (!externalAnchorRef && !isValidElement(children)) return children;

  // The label describes the trigger, so it has to name the trigger itself.
  // Everything else the tooltip needs is read off the anchor below instead of
  // cloned on: a handler written onto the child is the child's handler as far
  // as that child can tell, and a component that owns its activation —
  // hard-wiring onClick and spreading the rest of its props over it, as
  // ThemeToggle does — then runs the tooltip's instead of its own. Composing
  // with `props.onClick` cannot save it either, because a component element's
  // props hold nothing the component does internally.
  const trigger = isValidElement(children)
    ? cloneElement(children as ReactElement<Record<string, unknown>>, {
        "aria-describedby":
          [(children.props as Record<string, unknown>)["aria-describedby"], open ? id : undefined]
            .filter(Boolean)
            .join(" ") || undefined,
      })
    : null;

  return (
    <>
      {!externalAnchorRef ? (
        // biome-ignore lint/a11y/noStaticElementInteractions: This wrapper observes bubbling trigger events without replacing the control's handlers.
        <span
          ref={wrapperRef}
          className={cn("relative inline-flex align-middle", wrapperClassName)}
          // Pointer events, not the mouse pair: a tap fires compatibility
          // mouseenter/mouseleave that carry no pointerType, which raced the tap
          // path into opening and closing the same label.
          onPointerEnter={(event: PointerEvent) => {
            if (hover.enter(event)) show();
          }}
          onPointerLeave={(event: PointerEvent) => {
            if (hover.leave(event)) leave();
          }}
          onFocus={() => {
            focused.current = true;
            show();
          }}
          onBlur={() => {
            focused.current = false;
            hide();
          }}
          onPointerDown={(event: PointerEvent) => tap.start(event, open)}
          // A gesture the platform took away sends no click, and a key press
          // starts an activation that never had a pointer behind it. Either way
          // the record has to go, or the next click reads a finger that has long
          // since lifted.
          onPointerCancel={tap.drop}
          onKeyDown={(event) => {
            tap.drop();
            if (event.key === "Escape") hide();
          }}
          onClick={toggleOnTap}
        >
          {trigger}
        </span>
      ) : null}
      {typeof document !== "undefined"
        ? createPortal(
            <AnimatePresence>
              {open ? (
                <TooltipPositioner
                  key="tooltip"
                  anchorRef={anchorRef}
                  floatingRef={floatingRef}
                  anchorPoint={anchorPoint}
                  followCursor={followCursor}
                  side={side}
                  onDismiss={hide}
                  pointer={pointer}
                >
                  {(positioned, isPresent) => (
                    <TooltipSurface
                      id={id}
                      ready={positioned}
                      side={side}
                      onPointerEnter={() => {
                        if (timer.current) clearTimeout(timer.current);
                      }}
                      onPointerLeave={leave}
                      style={{
                        maxWidth: "calc(100vw - 16px)",
                        whiteSpace: "normal",
                        pointerEvents: isPresent && !followCursor ? "auto" : "none",
                      }}
                      className={cn("overflow-hidden", className)}
                    >
                      {content}
                    </TooltipSurface>
                  )}
                </TooltipPositioner>
              ) : null}
            </AnimatePresence>,
            document.body,
          )
        : null}
    </>
  );
}

